<template>
  <div>
    <b-navbar
      toggleable="lg"
      type="dark"
      class="navbar-mbr shadow-sm py-2"
      fixed="top"
    >
      <b-container fluid>
        <b-navbar-brand to="/" class="d-flex align-items-center">
          <div class="logo-wrapper bg-white p-1 mr-2 shadow-sm">
            <img
              :src="company.companyLogo"
              alt="MBR Logo"
              width="45"
              height="45"
            />
          </div>
          <span class="brand-text font-weight-bold" v-if="company">{{
            company.smsSender
          }}</span>
        </b-navbar-brand>

        <b-navbar-toggle target="nav-collapse"></b-navbar-toggle>

        <b-collapse id="nav-collapse" is-nav>
          <b-navbar-nav class="ml-4 nav-links">
            <b-nav-item to="/customers" active-class="active">
              <b-icon icon="people" class="mr-1"></b-icon> Mutuários
            </b-nav-item>

            <b-nav-item to="/payments" active-class="active">
              <b-icon icon="wallet2" class="mr-1"></b-icon> Pagamentos
            </b-nav-item>

            <b-nav-item to="/prestacoes" active-class="active">
              <b-icon icon="calendar-check" class="mr-1"></b-icon> Prestações
            </b-nav-item>

            <b-nav-item to="/reports" active-class="active">
              <b-icon icon="graph-up" class="mr-1"></b-icon> Relatórios
            </b-nav-item>

            <b-nav-item
              to="/settings"
              v-if="user.userRole == 1"
              active-class="active"
            >
              <b-icon icon="gear" class="mr-1"></b-icon> Configurações
            </b-nav-item>
          </b-navbar-nav>

          <b-navbar-nav class="ml-auto align-items-center">
            <!-- Sino de Notificações -->
            <b-nav-item-dropdown
              right
              no-caret
              class="notification-dropdown mr-2"
              @show="onNotificationDropdownShow"
            >
              <template #button-content>
                <div class="notification-bell position-relative">
                  <b-icon icon="bell-fill" font-scale="1.2" class="text-white"></b-icon>
                  <b-badge
                    v-if="unreadCount > 0"
                    variant="danger"
                    pill
                    class="notification-badge"
                  >
                    {{ unreadCount > 99 ? '99+' : unreadCount }}
                  </b-badge>
                </div>
              </template>

              <b-dropdown-header class="d-flex justify-content-between align-items-center notification-header">
                <strong>Notificações</strong>
                <b-button
                  v-if="unreadCount > 0"
                  variant="link"
                  size="sm"
                  class="p-0 text-success"
                  @click.stop="markAllRead"
                >
                  <small>Marcar todas como lidas</small>
                </b-button>
              </b-dropdown-header>

              <b-dropdown-divider></b-dropdown-divider>

              <div class="notification-list" style="max-height: 350px; overflow-y: auto; width: 340px">
                <div v-if="notifications.length === 0" class="text-center py-4">
                  <b-icon icon="bell-slash" font-scale="2" class="text-muted mb-2 d-block mx-auto"></b-icon>
                  <small class="text-muted">Sem notificações</small>
                </div>

                <b-dropdown-item-button
                  v-for="notif in notifications"
                  :key="notif.id"
                  class="notification-item"
                  :class="{ 'unread': !notif.isRead }"
                  @click="onNotificationClick(notif)"
                >
                  <div class="d-flex align-items-start">
                    <div class="notif-icon mr-2 mt-1" :class="'notif-icon-' + notif.type">
                      <b-icon :icon="getNotifIcon(notif.type)" font-scale="0.85"></b-icon>
                    </div>
                    <div class="flex-grow-1" style="min-width: 0">
                      <div class="font-weight-bold small text-truncate" style="color: #333">{{ notif.title }}</div>
                      <small class="text-muted d-block text-truncate">{{ notif.message }}</small>
                      <small class="text-muted" style="font-size: 0.7rem">{{ timeAgo(notif.createdAt) }}</small>
                    </div>
                    <div v-if="!notif.isRead" class="ml-2 mt-1">
                      <span class="unread-dot"></span>
                    </div>
                  </div>
                </b-dropdown-item-button>
              </div>

              <b-dropdown-divider></b-dropdown-divider>
              <b-dropdown-item to="/notificacoes" class="text-center">
                <small class="font-weight-bold" style="color: #009640">Ver todas as notificações</small>
              </b-dropdown-item>
            </b-nav-item-dropdown>

            <b-nav-item-dropdown right no-caret class="profile-dropdown">
              <template #button-content>
                <div class="user-badge d-flex align-items-center px-3 py-1">
                  <div class="text-right mr-2 d-none d-md-block">
                    <small class="d-block text-light opacity-75"
                      >Bem-vindo,</small
                    >
                    <span class="font-weight-bold">{{ user.name }}</span>
                  </div>
                  <b-avatar
                    variant="light"
                    size="2.2rem"
                    class="text-mbr-green"
                  >
                    <b-icon icon="person-fill"></b-icon>
                  </b-avatar>
                </div>
              </template>

              <b-dropdown-header class="text-uppercase small font-weight-bold"
                >Minha Conta</b-dropdown-header
              >
              <b-dropdown-item to="/profile">
                <b-icon icon="person-circle" class="mr-2"></b-icon> Meu Perfil
              </b-dropdown-item>

              <b-dropdown-item to="/logs" v-if="user.userRole == 1">
                <b-icon icon="journal-text" class="mr-2"></b-icon> Histórico
              </b-dropdown-item>

              <b-dropdown-divider></b-dropdown-divider>

              <b-dropdown-item @click="logoutUser()" variant="danger">
                <b-icon icon="power" class="mr-2"></b-icon> Sair do Sistema
              </b-dropdown-item>
            </b-nav-item-dropdown>
          </b-navbar-nav>
        </b-collapse>
      </b-container>
    </b-navbar>

    <div style="margin-top: 75px"></div>
  </div>
</template>

<script>
import axios from "axios";
import moment from "moment";
import { mapGetters } from "vuex";
import logs from "@/utils/logs";

export default {
  data: () => ({
    language: "PT",
    // Notificações
    notifications: [],
    unreadCount: 0,
    notifPollingTimer: null,
  }),

  computed: {
    ...mapGetters(["user", "token", "company"]),
  },

  created() {
    if (this.token) {
      axios.defaults.headers.common["Authorization"] = `Bearer ${this.token}`;
      this.getCompany();
    }
  },

  beforeDestroy() {
    if (this.notifPollingTimer) {
      clearInterval(this.notifPollingTimer);
    }
  },

  methods: {
    logoutUser() {
      if (this.notifPollingTimer) {
        clearInterval(this.notifPollingTimer);
        this.notifPollingTimer = null;
      }
      const logsParams = logs(
        this.user,
        `${this.user.email} - ${this.user.name} terminou a sessão.`,
        "Autenticação"
      );
      this.$store.dispatch("addLog", logsParams).then(() => {
        this.$store.dispatch("actionDoLogout");
        this.$router.push("/");
      });
    },

    getCompany() {
      this.$store
        .dispatch("getCompanyDetails", this.user.companyId)
        .then(() => {
          this.$store.dispatch("getAllRates", this.company.id);
          this.$store.dispatch("getCompanyLoans", this.company.id);
          // Iniciar polling de notificações após carregar company
          this.fetchUnreadCount();
          this.notifPollingTimer = setInterval(() => {
            this.fetchUnreadCount();
          }, 30000);
        })
        .catch((err) => {
          console.log(err.message);
          this.logoutUser();
        });
    },

    // ── Notificações ──
    async fetchUnreadCount() {
      if (!this.company || !this.company.id) return;
      try {
        const recipientType = Number(this.user.userRole) === 0 ? "admin" : "gestor";
        const res = await axios.get(
          `/api/notifications/unread/${this.company.id}?recipientType=${recipientType}&recipientId=${this.user.id}`
        );
        if (res.data.success) this.unreadCount = res.data.result;
      } catch (err) { /* silenciar */ }
    },

    async onNotificationDropdownShow() {
      if (!this.company || !this.company.id) return;
      try {
        const recipientType = Number(this.user.userRole) === 0 ? "admin" : "gestor";
        const res = await axios.get(
          `/api/notifications/${this.company.id}?recipientType=${recipientType}&recipientId=${this.user.id}`
        );
        if (res.data.success) this.notifications = res.data.result;
      } catch (err) { console.error("Erro notificações:", err); }
    },

    async onNotificationClick(notif) {
      if (!notif.isRead) {
        try {
          await axios.put(`/api/notifications/read/${notif.id}`);
          notif.isRead = true;
          this.unreadCount = Math.max(0, this.unreadCount - 1);
        } catch (err) { /* silenciar */ }
      }
    },

    async markAllRead() {
      if (!this.company || !this.company.id) return;
      try {
        const recipientType = Number(this.user.userRole) === 0 ? "admin" : "gestor";
        await axios.put(`/api/notifications/markAllRead/${this.company.id}`, {
          recipientType,
          recipientId: this.user.id,
        });
        this.notifications.forEach((n) => (n.isRead = true));
        this.unreadCount = 0;
      } catch (err) { console.error("Erro marcar lidas:", err); }
    },

    getNotifIcon(type) {
      const icons = {
        loan_request: "credit-card-2-front",
        loan_approved: "check-circle-fill",
        loan_rejected: "x-circle-fill",
        loan_disbursed: "cash-stack",
        payment_received: "wallet2",
        installment_due: "clock",
        installment_overdue: "exclamation-triangle-fill",
        general: "info-circle-fill",
      };
      return icons[type] || "bell";
    },

    timeAgo(date) {
      if (!date) return "";
      const m = moment(date);
      const diffMin = moment().diff(m, "minutes");
      if (diffMin < 1) return "Agora mesmo";
      if (diffMin < 60) return `Há ${diffMin} min`;
      const diffH = moment().diff(m, "hours");
      if (diffH < 24) return `Há ${diffH}h`;
      const diffD = moment().diff(m, "days");
      if (diffD < 7) return `Há ${diffD}d`;
      return m.format("DD/MM/YYYY");
    },
  },
};
</script>

<style scoped>
/* Estilização Base com as cores MBR */
.navbar-mbr {
  background: linear-gradient(90deg, #009640 0%, #007a33 100%);
  border-bottom: 3px solid #c5a065; /* Dourado do Logo */
}

.brand-text {
  font-size: 1.3rem;
  letter-spacing: 1px;
  color: white;
}

.logo-wrapper {
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.2);
}

/* Links de Navegação */
.nav-links .nav-link {
  color: rgba(255, 255, 255, 0.85) !important;
  font-weight: 500;
  padding: 0.5rem 1rem !important;
  transition: all 0.3s ease;
  border-bottom: 2px solid transparent;
}

.nav-links .nav-link:hover {
  color: white !important;
  background-color: rgba(255, 255, 255, 0.1);
  border-radius: 4px;
}

.nav-links .active {
  color: white !important;
  border-bottom: 2px solid #c5a065 !important; /* Dourado */
}

/* Badge do Usuário */
.user-badge {
  background-color: rgba(0, 0, 0, 0.15);
  border-radius: 50px;
  transition: background 0.3s;
}

.user-badge:hover {
  background-color: rgba(0, 0, 0, 0.25);
}

.text-mbr-green {
  color: #009640;
}

.opacity-75 {
  opacity: 0.75;
}

/* ==================== Notificações ==================== */
.notification-bell {
  padding: 6px 10px;
  border-radius: 50%;
  transition: background 0.2s;
  cursor: pointer;
}
.notification-bell:hover {
  background: rgba(255, 255, 255, 0.15);
}
.notification-badge {
  position: absolute;
  top: 0;
  right: 2px;
  font-size: 0.6rem;
  min-width: 16px;
  height: 16px;
  line-height: 16px;
  padding: 0 4px;
  animation: notifPulse 2s infinite;
}
@keyframes notifPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(220, 53, 69, 0.4); }
  50% { box-shadow: 0 0 0 6px rgba(220, 53, 69, 0); }
}
.notification-header {
  min-width: 300px;
}
.notification-item {
  border-bottom: 1px solid #f0f0f0;
}
.notification-item.unread {
  background-color: #f0faf4;
}
.notification-item:last-child {
  border-bottom: none;
}
.notif-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.notif-icon-loan_request { background: #fff3cd; color: #856404; }
.notif-icon-loan_approved { background: #d4edda; color: #155724; }
.notif-icon-loan_rejected { background: #f8d7da; color: #721c24; }
.notif-icon-loan_disbursed { background: #d1ecf1; color: #0c5460; }
.notif-icon-payment_received { background: #d4edda; color: #155724; }
.notif-icon-installment_due { background: #fff3cd; color: #856404; }
.notif-icon-installment_overdue { background: #f8d7da; color: #721c24; }
.notif-icon-general { background: #d1ecf1; color: #0c5460; }
.unread-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #009640;
}

/* Ajustes Mobile */
@media (max-width: 991.98px) {
  .nav-links {
    margin-left: 0 !important;
    padding: 1rem 0;
  }
  .user-badge {
    margin-top: 1rem;
    justify-content: center;
  }
}
</style>
