<template>
  <div class="notifications-view bg-light min-vh-100">
    <NavBarVue />

    <b-container fluid class="py-4">
      <b-row class="justify-content-center">
        <b-col lg="10">

          <!-- Cabeçalho -->
          <b-card no-body class="border-0 shadow-sm mb-4">
            <b-card-body class="p-4">
              <b-row align-v="center">
                <b-col md="5">
                  <h4 class="text-dark font-weight-bold mb-1">
                    <b-icon icon="bell-fill" class="text-mbr-green mr-2"></b-icon>
                    Notificações
                  </h4>
                  <p class="text-muted small mb-0">{{ unreadCount }} não lida(s) de {{ allNotifications.length }} total</p>
                </b-col>
                <b-col md="7" class="text-md-right mt-3 mt-md-0">
                  <b-form-radio-group
                    v-model="filterStatus"
                    buttons
                    button-variant="outline-mbr"
                    size="sm"
                    class="mbr-radio-group mr-2"
                  >
                    <b-form-radio value="all">Todas</b-form-radio>
                    <b-form-radio value="unread">Não lidas</b-form-radio>
                    <b-form-radio value="read">Lidas</b-form-radio>
                  </b-form-radio-group>
                  <b-button variant="outline-mbr-green" size="sm" class="mr-2" @click="markAllRead()" :disabled="unreadCount === 0">
                    <b-icon icon="check2-all" class="mr-1"></b-icon> Marcar todas como lidas
                  </b-button>
                  <b-button variant="mbr-green" size="sm" @click="fetchNotifications()" :disabled="loading">
                    <b-icon icon="arrow-repeat" class="mr-1" :animation="loading ? 'spin' : ''"></b-icon> Actualizar
                  </b-button>
                </b-col>
              </b-row>
            </b-card-body>
          </b-card>

          <!-- Lista de notificações -->
          <b-overlay :show="loading" rounded="sm" opacity="0.6">
            <div v-if="filteredNotifications.length === 0 && !loading" class="text-center py-5">
              <b-icon icon="bell-slash" font-scale="3" class="text-muted mb-3 d-block mx-auto"></b-icon>
              <h6 class="text-muted">Sem notificações{{ filterStatus !== 'all' ? ' para este filtro' : '' }}.</h6>
            </div>

            <transition-group name="notif-fade" tag="div">
              <b-card
                v-for="notif in paginatedList"
                :key="notif.id"
                no-body
                class="border-0 shadow-sm mb-2 notif-card"
                :class="{ 'notif-unread': !notif.isRead }"
              >
                <b-card-body class="py-3 px-4">
                  <div class="d-flex align-items-start">
                    <div class="notif-icon-circle mr-3 mt-1" :class="'notif-type-' + notif.type">
                      <b-icon :icon="getIcon(notif.type)" font-scale="0.9"></b-icon>
                    </div>
                    <div class="flex-grow-1" style="min-width: 0">
                      <div class="d-flex justify-content-between align-items-start">
                        <div>
                          <h6 class="font-weight-bold text-dark mb-1" style="font-size: 0.9rem">
                            {{ notif.title }}
                            <span v-if="!notif.isRead" class="unread-dot ml-1"></span>
                          </h6>
                          <p class="text-muted mb-1" style="font-size: 0.85rem">{{ notif.message }}</p>
                          <small class="text-muted">
                            <b-icon icon="clock" class="mr-1"></b-icon>{{ timeAgo(notif.createdAt) }}
                          </small>
                        </div>
                        <div class="d-flex flex-shrink-0 ml-3">
                          <b-button
                            v-if="!notif.isRead"
                            variant="link"
                            size="sm"
                            class="text-success p-1"
                            @click.stop="markRead(notif)"
                            v-b-tooltip.hover
                            title="Marcar como lida"
                          >
                            <b-icon icon="check2"></b-icon>
                          </b-button>
                          <b-button
                            variant="link"
                            size="sm"
                            class="text-danger p-1"
                            @click.stop="deleteNotif(notif)"
                            v-b-tooltip.hover
                            title="Eliminar"
                          >
                            <b-icon icon="trash"></b-icon>
                          </b-button>
                        </div>
                      </div>
                    </div>
                  </div>
                </b-card-body>
              </b-card>
            </transition-group>

            <!-- Paginação -->
            <div v-if="totalPages > 1" class="d-flex justify-content-between align-items-center mt-3">
              <small class="text-muted">{{ startIdx + 1 }}–{{ endIdx }} de {{ filteredNotifications.length }}</small>
              <b-pagination
                v-model="currentPage"
                :total-rows="filteredNotifications.length"
                :per-page="perPage"
                size="sm"
                class="mb-0"
                first-number
                last-number
                limit="5"
              ></b-pagination>
              <b-form-select v-model="perPage" :options="[15, 30, 50]" size="sm" style="width: 80px" @change="currentPage = 1"></b-form-select>
            </div>
          </b-overlay>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import axios from "axios";
import { mapGetters } from "vuex";
import moment from "moment";
import NavBarVue from "@/components/NavBar";

export default {
  name: "NotificationsView",
  components: { NavBarVue },

  data: () => ({
    allNotifications: [],
    loading: false,
    filterStatus: "all",
    currentPage: 1,
    perPage: 15,
  }),

  created() {
    this.fetchNotifications();
  },

  computed: {
    ...mapGetters(["user", "company"]),

    unreadCount() {
      return this.allNotifications.filter((n) => !n.isRead).length;
    },
    filteredNotifications() {
      if (this.filterStatus === "unread") return this.allNotifications.filter((n) => !n.isRead);
      if (this.filterStatus === "read") return this.allNotifications.filter((n) => n.isRead);
      return this.allNotifications;
    },
    totalPages() { return Math.ceil(this.filteredNotifications.length / this.perPage); },
    startIdx() { return (this.currentPage - 1) * this.perPage; },
    endIdx() { return Math.min(this.startIdx + this.perPage, this.filteredNotifications.length); },
    paginatedList() { return this.filteredNotifications.slice(this.startIdx, this.endIdx); },
  },

  watch: {
    filterStatus() { this.currentPage = 1; },
  },

  methods: {
    async fetchNotifications() {
      if (!this.company || !this.company.id) return;
      this.loading = true;
      try {
        const res = await axios.get(`/api/notifications/${this.company.id}`, {
          params: { recipientType: "admin" },
        });
        if (res.data.success) this.allNotifications = res.data.result;
      } catch (err) {
        console.error("Erro ao carregar notificações:", err);
      } finally {
        this.loading = false;
      }
    },

    async markRead(notif) {
      try {
        await axios.put(`/api/notifications/read/${notif.id}`);
        notif.isRead = true;
      } catch (err) {
        console.error(err);
      }
    },

    async markAllRead() {
      if (!this.company || !this.company.id) return;
      try {
        await axios.put(`/api/notifications/markAllRead/${this.company.id}`, {
          recipientType: "admin",
        });
        this.allNotifications.forEach((n) => (n.isRead = true));
      } catch (err) {
        console.error(err);
      }
    },

    async deleteNotif(notif) {
      try {
        await axios.delete(`/api/notifications/${notif.id}`);
        this.allNotifications = this.allNotifications.filter((n) => n.id !== notif.id);
      } catch (err) {
        console.error(err);
      }
    },

    getIcon(type) {
      const icons = {
        loan_request: "credit-card-2-front",
        loan_approved: "check-circle-fill",
        loan_rejected: "x-circle-fill",
        loan_disbursed: "cash-stack",
        payment_received: "wallet-fill",
        installment_due: "calendar-event",
        installment_overdue: "exclamation-triangle-fill",
        general: "info-circle-fill",
      };
      return icons[type] || "bell";
    },

    timeAgo(date) {
      return moment(date).fromNow();
    },
  },
};
</script>

<style scoped>
.text-mbr-green { color: #009640 !important; }
.bg-mbr-green { background-color: #009640 !important; }
.btn-mbr-green { background-color: #009640; color: white; border: none; }
.btn-mbr-green:hover { background-color: #007a33; color: white; }
.btn-outline-mbr-green { color: #009640; border-color: #009640; }
.btn-outline-mbr-green:hover { background-color: #009640; color: white; }
.mbr-radio-group .btn-outline-mbr { border-color: #dee2e6; color: #6c757d; background-color: white; }
.mbr-radio-group .btn-outline-mbr:not(:disabled):not(.disabled).active { background-color: #009640; border-color: #009640; color: white; }

.notif-card { transition: all 0.2s ease; border-left: 3px solid transparent !important; }
.notif-card:hover { transform: translateX(2px); }
.notif-unread { border-left: 3px solid #009640 !important; background-color: #f8fdf9; }

.notif-icon-circle {
  width: 36px; height: 36px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.notif-type-loan_request { background: #fff3cd; color: #856404; }
.notif-type-loan_approved { background: #d4edda; color: #155724; }
.notif-type-loan_rejected { background: #f8d7da; color: #721c24; }
.notif-type-loan_disbursed { background: #d1ecf1; color: #0c5460; }
.notif-type-payment_received { background: #d4edda; color: #155724; }
.notif-type-installment_due { background: #fff3cd; color: #856404; }
.notif-type-installment_overdue { background: #f8d7da; color: #721c24; }
.notif-type-general { background: #d1ecf1; color: #0c5460; }

.unread-dot {
  display: inline-block; width: 8px; height: 8px; border-radius: 50%;
